; base_stats.asm — per-species base stats, read by GetMonHeader.
;
; pret ref: data/pokemon/base_stats/*.asm:BaseStats
;
; Generated by tools/generators/gen_base_stats.py into assets/base_stats.inc. This carrier sits at the
; mirrored path dos_port/src/data/pokemon/base_stats.asm; it was part of src/data/pokemon_data.asm until 2026-08-16
; (docs/current_plan_data_path_mirror.md).
;
; Embedded data goes in .data per the linker rule in docs/assembly.md (.rodata has
; no output-section rule and reads back as zero).
bits 32

global BaseStats

section .data
align 4

%include "assets/base_stats.inc"
